from pathlib import Path
import re
p=Path('/home/ubuntu/labrkp-workforce/client/src/pages/Home.tsx')
s=p.read_text()
start=s.index('function WorkerDetail(')
end=s.index('\n\nexport default function Home()', start)
new=r'''function WorkerDetail({ worker, onClose, onBook, onRatingUpdated }: { worker: (typeof workers)[number]; onClose: () => void; onBook: () => void; onRatingUpdated: (summary: { rating: string; reviews: number }) => void }) {
  const [reviews, setReviews] = useState<any[]>([]);
  const [customerName, setCustomerName] = useState("");
  const [comment, setComment] = useState("");
  const [rating, setRating] = useState(5);
  const [reviewError, setReviewError] = useState("");
  const [reviewSent, setReviewSent] = useState(false);
  const workerId = String(worker.applicationId || worker.id);
  useEffect(() => { fetch(`/api/workers/${encodeURIComponent(workerId)}/reviews`).then((response) => response.ok ? response.json() : { reviews: [] }).then((data) => { setReviews(data.reviews || []); if (data.summary) onRatingUpdated(data.summary); }).catch(() => setReviews([])); }, [workerId, onRatingUpdated]);
  const submitReview = async () => {
    setReviewError("");
    if (!customerName.trim() || !comment.trim()) { setReviewError("Please enter your name and review."); return; }
    const response = await fetch(`/api/workers/${encodeURIComponent(workerId)}/reviews`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ customerName, comment, rating }) });
    const data = await response.json();
    if (!response.ok) { setReviewError(data.error || "Unable to submit review."); return; }
    setReviews((current) => [data.review, ...current]); onRatingUpdated(data.summary); setCustomerName(""); setComment(""); setReviewSent(true);
  };
  return <div className="fixed inset-0 z-40 overflow-y-auto bg-[#10201e]/60 p-4 backdrop-blur-sm"><div className="flex min-h-full items-center justify-center py-8"><div className="w-full max-w-4xl overflow-hidden rounded-[30px] bg-[#f8faf6] shadow-2xl"><div className="relative h-56 sm:h-72"><img src={worker.image} alt={worker.name} className="h-full w-full object-cover" /><div className="absolute inset-0 bg-gradient-to-t from-[#162524]/80 to-transparent" /><button onClick={onClose} className="absolute right-5 top-5 grid h-10 w-10 place-items-center rounded-full bg-white/90 text-[#263c37]"><X size={18} /></button><div className="absolute bottom-5 left-6 right-6 flex flex-col justify-between gap-4 text-white sm:flex-row sm:items-end"><div><div className="flex items-center gap-2"><h2 className="font-display text-3xl font-semibold">{worker.name}</h2><VerifiedMark /></div><p className="mt-1 text-sm text-white/75">{worker.role} · {worker.city}</p></div><button onClick={onBook} className="flex items-center justify-center gap-2 rounded-full bg-[#d7f477] px-5 py-3 text-sm font-bold text-[#263b31]">Book this worker <ArrowRight size={16} /></button></div></div><div className="grid gap-8 p-6 sm:grid-cols-[1.1fr_0.9fr] sm:p-8"><div><div className="flex flex-wrap gap-2"><Pill tone="green"><ShieldCheck size={13} className="mr-1" />Verified LABRKP worker</Pill><Pill tone="green"><Check size={13} className="mr-1" />CNIC · Phone · Address checked</Pill><Pill><Star size={13} className="mr-1 fill-[#c18b27] text-[#c18b27]" />{worker.rating} · {worker.reviews} reviews</Pill><Pill><UsersRound size={13} className="mr-1" />{worker.jobs} jobs completed</Pill></div><p className="mt-6 text-sm leading-7 text-[#5f6e68]">{worker.bio} {worker.name} is known for clear communication, punctual arrivals and work that holds up beyond the handover.</p><div className="mt-7"><div className="flex items-center justify-between"><h3 className="font-display text-xl font-semibold text-[#1c2c2a]">Services & pricing</h3><span className="text-xs text-[#8b9992]">Updated this week</span></div><div className="mt-4 space-y-3">{worker.services.map((item) => <div key={item.name} className="flex items-center justify-between gap-4 rounded-2xl border border-[#e4ebe0] bg-white px-4 py-3.5"><div><p className="text-sm font-semibold text-[#2c403a]">{item.name}</p><p className="mt-1 flex items-center gap-1 text-xs text-[#8b9992]"><Clock3 size={12} />{item.duration}</p></div><p className="font-display text-base font-semibold text-[#2b493d]">{item.price}</p></div>)}</div></div><div className="mt-8 border-t border-[#e4ebe0] pt-6"><div className="flex items-center justify-between"><h3 className="font-display text-xl font-semibold text-[#1c2c2a]">Customer reviews</h3><span className="text-xs text-[#8b9992]">{reviews.length} submitted</span></div><div className="mt-4 space-y-3">{reviews.slice(0, 3).map((review) => <div key={review.reviewId} className="rounded-2xl bg-white p-4"><div className="flex items-center justify-between gap-3"><p className="text-sm font-semibold text-[#2c403a]">{review.customerName}</p><span className="flex items-center gap-1 text-xs font-bold text-[#9b7424]"><Star size={12} className="fill-current" />{review.rating}/5</span></div><p className="mt-2 text-sm leading-6 text-[#718078]">{review.comment}</p></div>)}{reviews.length === 0 && <p className="rounded-2xl bg-white p-4 text-sm text-[#819087]">No reviews yet — be the first customer to share feedback.</p>}</div><div className="mt-5 rounded-2xl bg-[#edf5e5] p-4"><p className="text-sm font-semibold text-[#314a3c]">Share your experience</p><div className="mt-3 grid gap-3 sm:grid-cols-2"><input value={customerName} onChange={(event) => setCustomerName(event.target.value)} placeholder="Your name" className="rounded-xl border border-[#d7e5d1] bg-white px-3 py-2.5 text-sm outline-none focus:border-[#8aab62]" /><select value={rating} onChange={(event) => setRating(Number(event.target.value))} className="rounded-xl border border-[#d7e5d1] bg-white px-3 py-2.5 text-sm outline-none"><option value={5}>5 stars — Excellent</option><option value={4}>4 stars — Good</option><option value={3}>3 stars — Okay</option><option value={2}>2 stars — Needs improvement</option><option value={1}>1 star — Poor</option></select></div><textarea value={comment} onChange={(event) => setComment(event.target.value)} rows={3} placeholder="Tell future customers about the service..." className="mt-3 w-full resize-none rounded-xl border border-[#d7e5d1] bg-white px-3 py-2.5 text-sm outline-none focus:border-[#8aab62]" />{reviewError && <p className="mt-2 text-xs font-semibold text-[#a45843]">{reviewError}</p>}{reviewSent && <p className="mt-2 text-xs font-semibold text-[#52733e]">Thank you — the worker rating has been updated.</p>}<button onClick={() => void submitReview()} className="mt-3 rounded-full bg-[#203a34] px-4 py-2.5 text-xs font-bold text-white">Submit review</button></div></div></div><aside className="rounded-[24px] bg-[#edf5e5] p-5"><p className="text-xs font-bold uppercase tracking-[0.16em] text-[#71846f]">Expertise</p><div className="mt-4 flex flex-wrap gap-2">{[...worker.tags, "On-site support", "Safety first"].map((tag) => <span key={tag} className="rounded-full bg-white px-3 py-2 text-xs font-semibold text-[#496052]">{tag}</span>)}</div><div className="my-6 h-px bg-[#d7e5d1]" /><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-2xl bg-[#d7f477] text-[#395a37]"><Compass size={19} /></div><div><p className="text-sm font-semibold text-[#314a3c]">Works within 25 km</p><p className="mt-0.5 text-xs text-[#78907b]">Live location shared on active jobs</p></div></div><div className="mt-4 flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-2xl bg-white text-[#607d65]"><MessageCircle size={18} /></div><div><p className="text-sm font-semibold text-[#314a3c]">Quick response</p><p className="mt-0.5 text-xs text-[#78907b]">Usually replies within 12 min</p></div></div></aside></div></div></div></div>;
}'''
s=s[:start]+new+s[end:]
# Add URL sync after state declarations
needle='  const [minRating, setMinRating] = useState("0");\n\n'
url='''  const [minRating, setMinRating] = useState("0");

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    setWorkforce(params.get("workforce") === "Female" ? "Female" : "Male");
    setQuery(params.get("q") || ""); setActiveCategory(params.get("category") || "All services"); setLocationFilter(params.get("location") || "All locations");
    setMinPrice(params.get("minPrice") || ""); setMaxPrice(params.get("maxPrice") || ""); setMinRating(params.get("minRating") || "0"); setSort(params.get("sort") || "Recommended");
  }, []);
  useEffect(() => {
    const params = new URLSearchParams();
    if (workforce !== "Male") params.set("workforce", workforce); if (query) params.set("q", query); if (activeCategory !== "All services") params.set("category", activeCategory); if (locationFilter !== "All locations") params.set("location", locationFilter);
    if (minPrice) params.set("minPrice", minPrice); if (maxPrice) params.set("maxPrice", maxPrice); if (minRating !== "0") params.set("minRating", minRating); if (sort !== "Recommended") params.set("sort", sort);
    window.history.replaceState({}, "", `${window.location.pathname}${params.toString() ? `?${params.toString()}` : ""}`);
  }, [activeCategory, locationFilter, maxPrice, minPrice, minRating, query, sort, workforce]);

'''
if needle not in s: raise SystemExit('state anchor missing')
s=s.replace(needle,url,1)
# update modal mounting
s=s.replace('{selectedWorker && !bookingWorker && <WorkerDetail worker={selectedWorker} onClose={() => setSelectedWorker(null)} onBook={() => { setBookingWorker(selectedWorker); setSelectedWorker(null); }} />}', '{selectedWorker && !bookingWorker && <WorkerDetail worker={selectedWorker} onClose={() => setSelectedWorker(null)} onRatingUpdated={(summary) => setSelectedWorker((current) => current ? { ...current, rating: summary.rating, reviews: summary.reviews } : current)} onBook={() => { setBookingWorker(selectedWorker); setSelectedWorker(null); }} />}')
p.write_text(s)
